&lt;Routes&gt;
  &lt;Route path=&quot;/&quot; element={&lt;Layout /&gt;}&gt;
    &lt;Route index element={&lt;Activity /&gt;} /&gt;
    &lt;Route path=&quot;invoices&quot; element={&lt;Invoices /&gt;} /&gt;
    &lt;Route path=&quot;activity&quot; element={&lt;Activity /&gt;} /&gt;
  &lt;/Route&gt;
&lt;/Routes&gt;
使用Outlet来渲染子路由元素
function Layout() {
  return (
    &lt;div&gt;
      &lt;h1&gt;Layout&lt;/h1&gt;
      &lt;Outlet /&gt;
    &lt;/div&gt;
  );
}
Hook
移除useHistory
useNavigate返回一个函数，该函数可以以编程方式进行导航
import { useNavigate } from &quot;react-router-dom&quot;;

function SignupForm() {
  let navigate = useNavigate();
  async function handleSubmit(event) {
    await submitForm(event.target);
    navigate(&quot;../success&quot;, { replace: true });
  }
  return &lt;form onSubmit={handleSubmit}&gt;{/* ... */}&lt;/form&gt;;
}
useRoutes可以替代react-router-config
import { useRoutes } from &quot;react-router-dom&quot;;
function App() {
  let element = useRoutes([
    {
      path: &quot;/&quot;,
      element: &lt;Dashboard /&gt;,
      children: [
        {
          path: &quot;messages&quot;,
          element: &lt;DashboardMessages /&gt;
        },
        { path: &quot;tasks&quot;, element: &lt;DashboardTasks /&gt; }
      ]
    },
    { path: &quot;team&quot;, element: &lt;AboutPage /&gt; }
  ]);
  return element;
}
匹配规则
/teams/new的URL两个Route的path都可以匹配上
但是teams/new比/teams/:teamId更加具体，所以会渲染NewTeamForm
&lt;Route path=&quot;teams/:teamId&quot; element={&lt;Team /&gt;} /&gt;
&lt;Route path=&quot;teams/new&quot; element={&lt;NewTeamForm /&gt;} /&gt;
原理解析
BrowserRouter
创建history对象，通过listen方法监听，如果路由发生变化则重新渲染
export function BrowserRouter({
  basename,
  children,
  window
}: BrowserRouterProps) {
  let historyRef = React.useRef&lt;BrowserHistory&gt;();
  if (historyRef.current == null) {
    historyRef.current = createBrowserHistory({ window });
  }

  let history = historyRef.current;
  let [state, setState] = React.useState({
    action: history.action,
    location: history.location
  });

  React.useLayoutEffect(() =&gt; history.listen(setState), [history]);

  return (
    &lt;Router
      basename={basename}
      children={children}
      location={state.location}
      navigationType={state.action}
      navigator={history}
    /&gt;
  );
}
Router
创建NavigationContext和LocationContext，对路径进行一些转换
export function Router({
  basename: basenameProp = &quot;/&quot;,
  children = null,
  location: locationProp,
  navigationType = NavigationType.Pop,
  navigator,
  static: staticProp = false
}: RouterProps): React.ReactElement | null {
  //  &#039;////abc&#039; =&gt; &#039;/abc&#039;
  let basename = normalizePathname(basenameProp);

  let navigationContext = React.useMemo(
    () =&gt; ({ basename, navigator, static: staticProp }),
    [basename, navigator, staticProp]
  );

  let {
    pathname = &quot;/&quot;,
    search = &quot;&quot;,
    hash = &quot;&quot;,
    state = null,
    key = &quot;default&quot;
  } = locationProp;

  let location = React.useMemo(() =&gt; {
     // (&#039;/abc/def&#039;,&#039;/abc&#039;) =&gt; &#039;/def&#039;
    let trailingPathname = stripBasename(pathname, basename);
    if (trailingPathname == null) {
      return null;
    }
    return {
      pathname: trailingPathname,
      search,
      hash,
      state,
      key
    };
  }, [basename, pathname, search, hash, state, key]);

  return (
    &lt;NavigationContext.Provider value={navigationContext}&gt;
      &lt;LocationContext.Provider
        children={children}
        value={{ location, navigationType }}
      /&gt;
    &lt;/NavigationContext.Provider&gt;
  );
}
Routes
Route组件必须包裹在Routes中，不会直接渲染
export function Route(
  _props: PathRouteProps | LayoutRouteProps | IndexRouteProps
): React.ReactElement | null {
  invariant(
    false,
    `A &lt;Route&gt; is only ever to be used as the child of &lt;Routes&gt; element, ` +
      `never rendered directly. Please wrap your &lt;Route&gt; in a &lt;Routes&gt;.`
  );
}
Routes通过useRoutes来实现
export function Routes({
  children,
  location
}: RoutesProps): React.ReactElement | null {
  return useRoutes(createRoutesFromChildren(children), location);
}
通过createRoutesFromChildren来处理children，变成配置的形式
export function createRoutesFromChildren(
  children: React.ReactNode
): RouteObject[] {
  let routes: RouteObject[] = [];

  React.Children.forEach(children, element =&gt; {
    if (!React.isValidElement(element)) {
      // Ignore non-elements. This allows people to more easily inline
      // conditionals in their route config.
      return;
    }

    if (element.type === React.Fragment) {
      // Transparently support React.Fragment and its children.
      routes.push.apply(
        routes,
        createRoutesFromChildren(element.props.children)
      );
      return;
    }

    invariant(
      element.type === Route,
      `[${
        typeof element.type === &quot;string&quot; ? element.type : element.type.name
      }] is not a &lt;Route&gt; component. All component children of &lt;Routes&gt; must be a &lt;Route&gt; or &lt;React.Fragment&gt;`
    );

    let route: RouteObject = {
      caseSensitive: element.props.caseSensitive,
      element: element.props.element,
      index: element.props.index,
      path: element.props.path
    };

    if (element.props.children) {
      route.children = createRoutesFromChildren(element.props.children);
    }

    routes.push(route);
  });

  return routes;
}
useRoutes会渲染匹配的element
matchRoutes会根据传入的路由配置和pathname获得匹配的数据
如果matches的长度大于1，表示有子路由存在
export function useRoutes(
  routes: RouteObject[],
  locationArg?: Partial&lt;Location&gt; | string
): React.ReactElement | null {

  // 必须在 Router 的上下文中使用
  invariant(
    useInRouterContext(),
    // TODO: This error is probably because they somehow have 2 versions of the
    // router loaded. We can help them understand how to avoid that.
    `useRoutes() may be used only in the context of a &lt;Router&gt; component.`
  );

  // ……
  // 获取各种参数ing
  // ……

  let pathname = location.pathname || &quot;/&quot;;
  let remainingPathname =
    parentPathnameBase === &quot;/&quot;
      ? pathname
      : pathname.slice(parentPathnameBase.length) || &quot;/&quot;;

  let matches = matchRoutes(routes, { pathname: remainingPathname });

  return _renderMatches(
    matches &amp;&amp;
      matches.map(match =&gt;
        Object.assign({}, match, {
          params: Object.assign({}, parentParams, match.params),
          pathname: joinPaths([parentPathnameBase, match.pathname]),
          pathnameBase:
            match.pathnameBase === &quot;/&quot;
              ? parentPathnameBase
              : joinPaths([parentPathnameBase, match.pathnameBase])
        })
      ),
    parentMatches
  );
}

在_renderMatches中返回由RouteContext.Provider包裹的匹配的element
通过reduceRight将子路由的element放到父路由Provider的value中
function _renderMatches(
  matches: RouteMatch[] | null,
  parentMatches: RouteMatch[] = []
): React.ReactElement | null {
  if (matches == null) return null;

  return matches.reduceRight((outlet, match, index) =&gt; {
    return (
      &lt;RouteContext.Provider
        children={
          match.route.element !== undefined ? match.route.element : &lt;Outlet /&gt;
        }
        value={{
          outlet,
          matches: parentMatches.concat(matches.slice(0, index + 1))
        }}
      /&gt;
    );
  }, null as React.ReactElement | null);
}
父路由中的Outlet组件通过useContext获取子路由的组件进行渲染
export function useOutlet(context?: unknown): React.ReactElement | null {
  let outlet = React.useContext(RouteContext).outlet;
  if (outlet) {
    return (
      &lt;OutletContext.Provider value={context}&gt;{outlet}&lt;/OutletContext.Provider&gt;
    );
  }
  return outlet;
}

React/React更新流程.content:
触发更新
创建一个用于保存更新状态相关信息的对象Update，包含action（新的状态或更新函数）、lane（更新的优先级）和next（多个更新会被串联成链表），会放到对应fiber节点的updateQueue上
更新发生在具体的组件上，但调度是从根节点开始的
执行markUpdateLaneFromFiberToRoot，从当前需要更新的fiber节点开始，根据父节点指针不断向上遍历直至root节点，并将更新优先级fiber.lane存入这一向上路径上所有祖先节点的childLanes中
childLanes字段在后续的render阶段遍历fiber树时用于判断子树中是否存在更新的依据
执行ensureRootIsScheduled
时机：新的更新产生、一个任务执行中途停止、执行完毕时
具体逻辑：

getNextLanes获取当前最高优先级
检查现有任务


优先级相同：直接复用，自动批处理的关键
优先级更高：取消旧任务，继续向下执行，准备开启高优先级的任务
优先级更低：同样直接返回。高优先级的跑完后会再次触发ensureRootIsScheduled


选择调度通道


同步线路：click、focus等离散事件后开启flushSync，放到微任务队列
并发线路：scroll、drag等连续事件或fetch、setTImeout等非交互式触发，会进入scheduler的时间分片流程，可以被中断

render阶段
根据最新的state和props在内存中构建一颗新的fiber树，计算最小的DOM变更量
递
从rootFiber开始向下深度优先遍历，为遍历到的每个Fiber节点调用beginWork 方法。
该方法会根据传入的Fiber节点创建子Fiber节点，并将这两个Fiber节点连接起来。
当遍历到叶子节点（即没有子组件的组件）时就会进入“归”阶段。
归
在“归”阶段会调用completeWork处理Fiber节点。
当某个Fiber节点执行完completeWork，如果其存在兄弟Fiber节点（即fiber.sibling !== null），会进入其兄弟Fiber的“递”阶段。
如果不存在兄弟Fiber，会进入父级Fiber的“归”阶段。
function App() {
  return (
    &lt;div&gt;
      i am
      &lt;span&gt;KaSong&lt;/span&gt;
    &lt;/div&gt;
  );
}

// rootFiber beginWork
// App Fiber beginWork
// div Fiber beginWork
// &quot;i am&quot; Fiber beginWork
// &quot;i am&quot; Fiber completeWork
// span Fiber beginWork
// span Fiber completeWork
// div Fiber completeWork
// App Fiber completeWork
// rootFiber completeWork
// 针对只有单一文本子节点的Fiber，React会特殊处理。
beginWork


mount阶段
会根据fiber.tag不同，创建不同类型的子Fiber节点


update阶段


if(current !== null) {
    const oldProps = current.memoizedProps;
     const newProps = workInProgress.pendingProps;

    if(oldProps !== newProps || hasLegacyContextChanges()) {
        didReceiveUpdate = true;
    } else if(!includesSomeLane(renderLanes, updateLanes)) {
        // 当前fiber.lanes优先级不够
        didReceiveUpdate = false;
        ...
        return bailoutOnAlreadyFinishedWork(current, workInProgress, renderLanes);
    } else {
        didReceiveUpdate = false;
    }
} else {
    didReceiveUpdate = false;
}

switch(workInProgress.tag) {
            ...
    case FunctionComponent:
        return updateFunctionComponent(...);
          case ClassComponent:
              return updateClassComponent(...);
    case MemoComponent:
        return updateMemoComponent(...);
    ...
}

判断oldProps === newProps （memo等方式缓存），如果有变动则无法复用current
当前fiber的更新优先级与此次fiber树的更新优先级判断，如果不存在更新或优先级不够，则执行bailoutOnAlreadyFinishedWork来复用fiber

// bailoutOnAlreadyFinishedWork会判断当前fiber节点的childLanes是否在本次更新的优先级信息renderLanes中
// 如果不是，则说明workInProgress的整棵子树中都不存在更新，所以直接返回null
// 如果是，则子树中存在更新，但是当前的fiber节点是可以复用的
function bailoutOnAlreadyFinishedWork(
  current: Fiber | null,
  workInProgress: Fiber,
  renderLanes: Lanes,
): Fiber | null {
      // ...
      if (!includesSomeLane(renderLanes, workInProgress.childLanes)) {
        return null;
      } else {
        cloneChildFibers(current, workInProgress);
        return workInProgress.child;
      }
  }

尝试命中优化手段


Class组件的shouldComponentUpdate，可以跳过则执行bailoutOnAlreadyFinishedWork
Function组件

function updateFunctionComponent(
  current,
  workInProgress,
  Component,
  nextProps: any,
  renderLanes
) {
      // 初始化hooks链表指针、执行函数主体返回ReactElement
      nextChildren = renderWithHooks();    

      // 如果存在待处理的hook更新，也会设置didReceiveUpdate
      if (current !== null &amp;&amp; !didReceiveUpdate) {
        bailoutHooks(current, workInProgress, renderLanes);        
        return bailoutOnAlreadyFinishedWork(current, workInProgress, renderLanes);
      }

      // 创建并返回下一个fiber节点
      reconcileChildren(current, workInProgress, nextChildren, renderLanes);
      return workInProgress.child;
}

function bailoutHooks(
  current: Fiber,
  workInProgress: Fiber,
  lanes: Lanes,
) {
  workInProgress.updateQueue = current.updateQueue;
  workInProgress.effectTag &amp;= ~(PassiveEffect | UpdateEffect);
  current.lanes = removeLanes(current.lanes, lanes);
}

没有命中优化手段，则执行reconcileChildren，标记effectTag

completeWork

mount：为Fiber节点生成对应的DOM节点、将子孙DOM节点插入刚生成的DOM节点中、处理props。
update：只是做了事件监听的注册和属性的预处理，赋值到fiber节点的updateQueue上，在commit阶段才会真正应用。

每个执行完completeWork且存在effectTag的Fiber节点会被保存在一条被称为effectList的单向链表中。
commit阶段
准备阶段
触发useEffect回调与其他同步任务，由于这些任务可能触发新的渲染，所以这里要一直遍历执行直到没有任务
主要是清理上一次渲染产生的回调任务（🌰：微任务 or useLayoutEffect里触发更新）
beforeMutation

处理DOM节点渲染/删除后的 autoFocus、blur 逻辑。
调用getSnapshotBeforeUpdate生命周期钩子。
调度useEffect，异步执行的原因主要是防止同步执行时阻塞浏览器渲染

mutation（执行dom操作）
遍历effectList，执行函数

Placement effect：调用parentNode.insertBefore或parentNode.appendChild执行DOM插入操作
Update effect：处理 updateQueue

FunctionComponent mutation：执行所有useLayoutEffect hook的销毁函数
HostComponent mutation：updateQueue对应的内容渲染在页面上（处理props）


Deletion effect：卸载不需要的节点，触发componentWillUnmount和useLayoutEffect的销毁函数

执行workInProgress到current的切换
layout
DOM已更新完毕，但浏览器还没有重绘，但此时 JS 已经可以获取到新的DOM

同步执行useLayoutEffect的回调、执行setState的回调
执行生命周期：componentDidMount或componentDidUpdate
