React/React闭包浅析.content:
🌰：
const cache = {};
let prevValue;

const something = (value) =&gt; {
  // 检查值是否改变
  if (!cache.current || value !== prevValue) {
    cache.current = () =&gt; {
      console.log(value);
    };
  }

  // 更新它
  prevValue = value;
  return cache.current;
};

const first = something(&#039;first&#039;);
const anotherFirst = something(&#039;first&#039;);
const second = something(&#039;second&#039;);

first(); // 打印 &quot;first&quot;
second(); // 打印 &quot;second&quot;
console.log(first === anotherFirst); // 返回 true
每次使用 useCallback 时，都会创建一个闭包，并且我们传递给它的函数会被缓存
const Component = () =&gt; {
  const [state, setState] = useState();

  const onClick = useCallback(() =&gt; {
    // state 将永远都是初始值
    // 闭包永远不会刷新
    console.log(state);

    // 忘记写依赖数组
  }, []);
};
解决方案：
使用useRef缓存
const [value, setValue] = useState();
const ref = useRef();

useEffect(() =&gt; {
  ref.current = () =&gt; {
    // 最新的值
    console.log(value);
  };
});

const onClick = useCallback(() =&gt; {
  // 最新的值
  ref.current();
}, []);

React/Redux-or-Mobx？原理浅析.content:
前言
React 社区生态繁荣，第三方库层出不穷。而在状态管理方面， Redux 和 Mobx 则是比较流行的两个轮子
Redux
简介
Redux 派生于 Flux 架构，提倡函数式编程
用单一 store 来保存 state，使用纯函数来修改 state
import { createStore } from &#039;redux&#039;

function counterReducer(state = { value: 0 }, action) {
  switch (action.type) {
    case &#039;increse&#039;:
      return { value: state.value + 1 }
    case &#039;descrese&#039;:
      return { value: state.value - 1 }
    default:
      return state
  }
}
const store = createStore(counterReducer)

store.subscribe(() =&gt; console.log(store.getState()))

store.dispatch({ type: &#039;increse&#039; })
// {value: 1}
store.dispatch({ type: &#039;increse&#039; })
// {value: 2}
store.dispatch({ type: &#039;descrese&#039; })
// {value: 1}
react-redux
Redux 和 Mobx 本身都是纯粹的状态管理库，并没有和 React 强绑定，如果想要在 React 中使用需要配合 react-redux 和 mobx-react 来使用
import { combineReducers, createStore } from &quot;redux&quot;;
import { Provider, useSelector, useDispatch } from &quot;react-redux&quot;;

const store = createStore(
  combineReducers({
    count(state = 0, action) {
      const { type } = action;
      switch (type) {
        case &quot;ADD_COUNT&quot;:
          return state + 1;
        default:
          return state;
      }
    },
    value(state = 0, action) {
      const { type } = action;
      switch (type) {
        case &quot;ADD_VALUE&quot;:
          return state + 1;
        default:
          return state;
      }
    },
  })
);

const Test = () =&gt; {
  const { count, value } = useSelector((store) =&gt; store);
  const dispatch = useDispatch();
  return (
    &lt;div&gt;
      &lt;h1 onClick={() =&gt; dispatch({ type: &quot;ADD_COUNT&quot; })}&gt;{count}&lt;/h1&gt;
      &lt;h1 onClick={() =&gt; dispatch({ type: &quot;ADD_VALUE&quot; })}&gt;{value}&lt;/h1&gt;
    &lt;/div&gt;
  );
};

function App() {
  return (
    &lt;div className=&quot;App&quot;&gt;
      &lt;Provider store={store}&gt;
        &lt;Test /&gt;
      &lt;/Provider&gt;
    &lt;/div&gt;
  );
}

export default App;
原理
Redux 通过闭包来维护数据，createStore返回三个方法，其中getState 用来获取在 createStore 中声明的 currentState ，通过 subscribe 来订阅事件，通过 reducer 来修改 currentState 的同时，会执行所有 subscribe 订阅的事件
function createStore(reducer, defaultState) {
  let listeners = [];
  let currentReducer = reducer;
  let currentState = defaultState;

  function dispatch(action) {
    currentState = currentReducer(currentState, action);
    for (let i = 0; i &lt; listeners.length; i++) {
      listeners[i]();
    }
  }

  function getState() {
    return currentState;
  }

  function subscribe(listen) {
    listeners.push(listen);
    return function () {
      listeners = listeners.filter((item) =&gt; item !== listen);
    };
  }

  dispatch({
    type: &quot;@@lyt-redux/init&quot;,
  });

  return {
    dispatch,
    getState,
    subscribe,
  };
}
react-redux通过context 将 Redux 的 store 注入到 Provider中，通过 useContext 即可获取store中的数据。为了使 state 发生变化的时候触发相应组件的更新，通过 subscribe 来订阅 forceUpdate ，当 dispatch 执行 reducer 更新 state 的时候，使用了 state 的组件就会触发订阅，更新组件
import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useState,
} from &quot;react&quot;;

const storeCtx = createContext();

function Provider({ store, children }) {
  return &lt;storeCtx.Provider value={store}&gt;{children}&lt;/storeCtx.Provider&gt;;
}

function useSelector(state) {
  const store = useStore();
  const forceUpdate = useForceUpdate();

  useLayoutEffect(() =&gt; {
    const sub = store.subscribe(() =&gt; forceUpdate());
    return () =&gt; sub();
  }, [forceUpdate, store]);
  return state(store.getState());
}

function useDispatch() {
  const { dispatch } = useStore();
  return dispatch;
}

function useStore() {
  const store = useContext(storeCtx);
  return store;
}

function useForceUpdate() {
  const [, setState] = useState(0);
  const forceUpdate = useCallback(() =&gt; setState((p) =&gt; p + 1), []);
  return forceUpdate;
}
如上的实现比较简单粗暴，使用了useSelector的地方都会触发更新，但在源码实现中，会缓存上一次的值，通过比较来判断是否需要更新
useIsomorphicLayoutEffect(() =&gt; {
    latestSelector.current = selector
    latestStoreState.current = storeState
    latestSelectedState.current = selectedState
    latestSubscriptionCallbackError.current = undefined
  })

useIsomorphicLayoutEffect(() =&gt; {
function checkForUpdates() {
  try {
    const newStoreState = store.getState()
    const newSelectedState = latestSelector.current!(newStoreState)

    if (equalityFn(newSelectedState, latestSelectedState.current)) {
      return
    }

    latestSelectedState.current = newSelectedState
    latestStoreState.current = newStoreState
  } catch (err) {
    // we ignore all errors here, since when the component
    // is re-rendered, the selectors are called again, and
    // will throw again, if neither props nor store state
    // changed
    latestSubscriptionCallbackError.current = err as Error
  }

  forceRender()
}

subscription.onStateChange = checkForUpdates
subscription.trySubscribe()

checkForUpdates()
Mobx
简介
Mobx 通过透明的函数式响应编程使状态管理变得简单和可拓展
通过proxy来实现数据的双向绑定，使状态变得可观察，视图可以响应状态的变化
import React from &quot;react&quot;
import ReactDOM from &quot;react-dom&quot;
import { makeAutoObservable } from &quot;mobx&quot;
import { observer } from &quot;mobx-react&quot;

// 对应用状态进行建模。
class Timer {
    secondsPassed = 0

    constructor() {
        makeAutoObservable(this)
    }

    increase() {
        this.secondsPassed += 1
    }

    reset() {
        this.secondsPassed = 0
    }
}

const myTimer = new Timer()

// 构建一个使用 observable 状态的“用户界面”。
const TimerView = observer(({ timer }) =&gt; (
    &lt;button onClick={() =&gt; timer.reset()}&gt;已过秒数：{timer.secondsPassed}&lt;/button&gt;
))

ReactDOM.render(&lt;TimerView timer={myTimer} /&gt;, document.body)

// 每秒更新一次‘已过秒数：X’中的文本。
setInterval(() =&gt; {
    myTimer.increase()
}, 1000)
原理
响应式的核心原理就是在get的时候track收集依赖，然后在set的时候triggle执行
import {
  memo,
  useState,
  useRef,
  FunctionComponent,
  MemoExoticComponent,
} from &quot;react&quot;;

type Effect = () =&gt; void;
type ProxyKey = string | symbol;

const effectStack: Effect[] = [];

const targetMap = new WeakMap&lt;object, Map&lt;ProxyKey, Effect[]&gt;&gt;();

function isObject(v: any): boolean {
  return v &amp;&amp; typeof v === &quot;object&quot;;
}

function track(target: object, key: ProxyKey) {
  let deps = targetMap.get(target);
  if (!deps) {
    deps = new Map();
    targetMap.set(target, deps);
  }

  let effectList = deps.get(key);
  if (!effectList) {
    effectList = [];
    deps.set(key, effectList);
  }

  if (effectStack.length !== 0) {
    effectList.push(effectStack[effectStack.length - 1]);
  }
}

function triggle(target: object, key: ProxyKey) {
  let deps = targetMap.get(target);
  if (!deps) {
    return;
  }

  const effectList = deps.get(key);
  if (effectList) {
    effectList.forEach((effect) =&gt; effect());
  }
}

function createObserable(target: any) {
  if (!isObject(target)) {
    return target;
  }
  for (let i in target) {
    target[i] = createObserable(target[i]);
  }
  return new Proxy(target, {
    get(target, key) {
      track(target, key);
      return Reflect.get(target, key);
    },
    set(target, key, value) {
      const r = Reflect.set(target, key, value);
      triggle(target, key);
      return r;
    },
  });
}

function useObserver&lt;T extends () =&gt; any&gt;(component: T): ReturnType&lt;T&gt; {
  const [_, forceUpdate] = useState([]);

  const result = useRef&lt;ReturnType&lt;T&gt;&gt;();

  if (!result.current) {
    effectStack.push(() =&gt; forceUpdate([]));
    result.current = component();
    effectStack.pop();
  } else {
    result.current = component();
  }
  return result.current as ReturnType&lt;T&gt;;
}

function obserable&lt;T extends object&gt;(target: T): T {
  return createObserable(target);
}

function observer&lt;T&gt;(
  component: FunctionComponent&lt;T&gt;
): MemoExoticComponent&lt;FunctionComponent&gt; {
  const WrapperComponent = (props: any) =&gt; {
    return useObserver(() =&gt; component(props));
  };
  return memo(WrapperComponent as any);
}

React/mini-react.content:
createElement
在React中通常使用JSX这一种语法拓展，可以很好地描述 UI 应该呈现出它应有交互的本质形式
但是在浏览器中无法直接使用JSX。在17版本之前，会通过Babel来将JSX转换成JavaScript代码，即React.createElement
// 源代码
import React from &#039;react&#039;;

function App() {
  return &lt;h1&gt;Hello World&lt;/h1&gt;;
}

// 转换后
import React from &#039;react&#039;;

function App() {
  return React.createElement(&#039;h1&#039;, null, &#039;Hello world&#039;);
}
createElement的实现比较简单，就返回一个Virtual Dom，简单来说就是一个对象
将children放到props里，所以children可以直接通过props.children来获取
但是需要额外判断一下children是字符串、数字等情况
返回一个type为TEXT_NODE的对象即可，然后把值放到props的nodeValue中，以便后续统一处理
function createElement(type, props, ...children) {
  return {
    type,
    props: {
      ...props,
      children: children.map((child) =&gt; {
        return typeof child === &quot;object&quot; ? child : createTextElement(child);
      }),

  };
}

function createTextElement(text) {
  return {
    type: &quot;TEXT_NODE&quot;,
    props: {
      nodeValue: text,
    },
  };
}
render
实现一个简单的render方法，把我们createElement返回的virtual dom渲染到页面上
类型是TEXT_NODE的通过createTextNode生成，其他的则通过createElement
先简单处理，直接将props除了children的属性全都放到dom上
children通过递归执行render
最后将生成的DOM添加到container中
function render(vdom, container) {
  const dom =
    vdom.type === &quot;TEXT_NODE&quot;
      ? document.createTextNode(&quot;&quot;)
      : document.createElement(vdom.type);

  vdom.props.children.forEach((child) =&gt; {
    render(child, dom);
  });

  Object.keys(vdom.props)
    .filter((key) =&gt; key !== &quot;children&quot;)
    .forEach((key) =&gt; (dom[key] = vdom.props[key]));

  container.appendChild(dom);
}
示例代码:(为了省事没有使用Babel等工具进行JSX的转换，所以直接写成createElement的形式)
&lt;div id=&quot;root&quot;&gt;&lt;/div&gt;
&lt;script src=&quot;react.js&quot;&gt;&lt;/script&gt;
&lt;script&gt;
  const element = createElement(
    &quot;h1&quot;,
    { className: &quot;title&quot; },
    createElement(&quot;span&quot;, {}, &quot;hello&quot;),
    createElement(&quot;span&quot;, {}, &quot;world&quot;)
  );
  render(element, document.getElementById(&quot;root&quot;));
&lt;/script&gt;
Concurrent Mode
render是通过递归来实现的，项目太过复杂就容易使JavaScript的执行时间过久，从而导致页面卡顿
所以想将render分成更小的工作单元，每完成一个单元的工作，允许浏览器打断来处理其他的事情
通过requestIdleCallback来进行简单实现，浏览器在线程空闲的时候主动执行回调函数
用全局变量nextUnitOfWork表示下一个工作单元
deadline是requestIdleCallback给回调函数的参数，用来获取这个渲染周期的剩余时间
当有下一个工作单元且还有剩余时间的时候执行performUnitOfWork函数
在这个函数中会进行工作单元的处理，并返回下一个工作单元
let nextUnitOfWork = null;

function wookLoop(deadline) {
  if (nextUnitOfWork &amp;&amp; deadline.timeRemaining() &gt; 1) {
    nextUnitOfWork = performUnitOfWork(nextUnitOfWork);
  }
  requestIdleCalback(wookLoop);
}
requestIdleCalback(wookLoop);

function performUnitOfWork() {
    // TODO
}
通过Fiber这种数据结构来描述工作单元，每一个Fiber都是一个单元任务
通过child来连接第一个子节点，其他的子节点都通过sibling根据第一个子节点依次连接，且都通过parent连接到父节点
先进行一下代码逻辑的调整
将render中创建dom的逻辑提取为createDom
function createDom(vdom) {
  const dom =
    vdom.type === &quot;TEXT_NODE&quot;
      ? document.createTextNode(&quot;&quot;)
      : document.createElement(vdom.type);

  Object.keys(vdom.props)
    .filter((key) =&gt; key !== &quot;children&quot;)
    .forEach((key) =&gt; (dom[key] = vdom.props[key]));

  return dom;
}
在render函数中进行nextUnitOfWork的赋值
function render(vdom, container) {
  nextUnitOfWork = {
    dom: container,
    props: {
      children: [vdom],
    },
  };
}
在performUnitOfWork中，主要做三个事情

创建dom节点
给子节点创建fiber
返回下一个单元任务

function performUnitOfWork(fiber) {
  // 1 创建dom节点
  if (!fiber.dom) {
    fiber.dom = createDom(fiber);
  }
  if (fiber.parent) {
    fiber.parent.dom.appendChild(fiber.dom);
  }

  // 2 给子节点创建fiber
  let index = 0;
  let prevSibling = null;
  const elements = fiber.props.children;
  while (index &lt; elements.length) {
    const element = elements[index];
    const newFiber = {
      parent: fiber,
      type: element.type,
      props: element.props,
      dom: null,
    };

    if (index === 0) {
      fiber.child = newFiber;
    } else {
      prevSibling.sibling = newFiber;
    }
    index++;
    prevSibling = newFiber;
  }

  // 3 返回下一个工作单元
  if (fiber.child) {
    return fiber.child;
  }
  let nextFiber = fiber;
  while (nextFiber) {
    if (nextFiber.sibling) {
      return nextFiber.sibling;
    }
    nextFiber = nextFiber.parent;
  }
  return null;
}
workInProgress
当我们用canvas绘制动画，每一帧绘制前都会调用ctx.clearRect清除上一帧的画面
如果当前帧画面计算量比较大，导致清除上一帧画面到绘制当前帧画面之间有较长间隙，就会出现白屏
为了解决这个问题，我们可以在内存中绘制当前帧动画，绘制完毕后直接用当前帧替换上一帧画面，由于省去了两帧替换间的计算时间，不会出现从白屏到出现画面的闪烁情况。
这种在内存中构建并直接替换的技术叫做双缓存
React使用“双缓存”来完成Fiber树的构建与替换——对应着Dom树的创建与更新
在React中最多会同时存在两棵Fiber树。当前屏幕上显示内容对应的Fiber树称为current fiber树
正在内存中构建的Fiber树称为workInProgress fiber 树
声明一个全局变量wipRoot，来表示构建中的fiber树
修改render的逻辑,给wipRoot赋值
function render(vdom, container) {
  wipRoot = {
    dom: container,
    props: {
      children: [vdom],
    },
  };
  nextUnitOfWork = wipRoot;
}
在wookLoop中，当wipRoot构建完毕后，即nextUnitOfWork为null的时候进行提交
function wookLoop(deadline) {
  if (nextUnitOfWork &amp;&amp; deadline.timeRemaining() &gt; 1) {
    nextUnitOfWork = performUnitOfWork(nextUnitOfWork);
  }
  if (!nextUnitOfWork &amp;&amp; wipRoot) {
    commitWork(wipRoot);
    wipRoot = null;
  }
  requestIdleCallback(wookLoop);
}

function commitWork(wipFiber) {
  if (!wipFiber) {
    return;
  }
  if (wipFiber.parent) {
    wipFiber.parent.dom.appendChild(wipFiber.dom);
  }
  commitWork(wipFiber.child);
  commitWork(wipFiber.sibling);
}
Reconciliation
目前只处理了页面挂载阶段时新加节点的情况
在页面更新时需要比较上次的fiber和当前渲染的fiber来决定哪些节点需要更新
全局声明一个变量currentRoot来保存上一次的fiber树
function wookLoop(deadline) {
  if (nextUnitOfWork &amp;&amp; deadline.timeRemaining() &gt; 1) {
    nextUnitOfWork = performUnitOfWork(nextUnitOfWork);
  }
  if (!nextUnitOfWork &amp;&amp; wipRoot) {
    commitWork(wipRoot);
    currentRoot = wipRoot;
    wipRoot = null;
  }
  requestIdleCallback(wookLoop);
}
同时给每一个fiber节点一个base属性指向上一次渲染的fiber
function render(vdom, container) {
  wipRoot = {
    dom: container,
    props: {
      children: [vdom],
    },
    base: currentRoot,
  };
  nextUnitOfWork = wipRoot;
}
在perfromUnitOfWork中执行reconcileChildren
function performUnitOfWork(fiber) {
  if (!fiber.dom) {
    fiber.dom = createDom(fiber);
  }

  const elements = fiber.props.children;
  reconcileChildren(fiber, elements);

  if (fiber.child) {
    return fiber.child;
  }

  let nextFiber = fiber;
  while (nextFiber) {
    if (nextFiber.sibling) {
      return nextFiber.sibling;
    }
    nextFiber = nextFiber.parent;
  }
  return null;
}
在reconcileChildren中进行新旧fiber的比较 打上effectTag
function reconcileChildren(wipFiber, elements) {
  let index = 0;
  let prevSibling = null;
  let oldFiber = fiber.base

  while (index &lt; elements.length &amp;&amp; oldFiber) {
    const element = elements[index];
    let newFiber = null;
    const sameType = element &amp;&amp; oldFiber &amp;&amp; oldFiber.type === element.type;
    // 如果前后fiber的type相同，则可以进行复用
    // 只需要更新props
    if (sameType) {
      newFiber = {
        type: oldFiber.type,
        props: element.props,
        dom: oldFiber.dom,
        parent: wipFiber,
        base: oldFiber,
        effectTag: &quot;UPDATE&quot;,
      };
    }
    // 类型不相同 需要创建新的dom
    if (element &amp;&amp; !sameType) {
      newFiber = {
        type: element.type,
        props: element.props,
        dom: null,
        parent: wipFiber,
        base: null,
        effectTag: &quot;PLACEMENT&quot;,
      };
    }
    // 类型不相同需要把老fiber给删除
    // 放入到deletions数组里
    if (oldFiber &amp;&amp; !sameType) {
      oldFiber.effectTag = &quot;DELETION&quot;;
      deletions.push(oldFiber);
    }
    if (oldFiber) {
      oldFiber = oldFiber.sibling;
    }

    if (index === 0) {
      wipFiber.child = newFiber;
    } else {
      prevSibling.sibling = newFiber;
    }
    index++;
    prevSibling = newFiber;
  }
}
deletions在全局声明，在render里进行初始化，提交时遍历执行commitWork
function render(vdom, container) {
  wipRoot = {
    dom: container,
    props: {
      children: [vdom],
    },
    base: currentRoot,
  };
  deletions = [];
  nextUnitOfWork = wipRoot;
}

function wookLoop(deadline) {
  if (nextUnitOfWork &amp;&amp; deadline.timeRemaining() &gt; 1) {
    nextUnitOfWork = performUnitOfWork(nextUnitOfWork);
  }
  if (!nextUnitOfWork &amp;&amp; wipRoot) {
    deletions.forEach(commitWork);
    commitWork(wipRoot);
    currentRoot = wipRoot;
    wipRoot = null;
    deletions = null;
  }
  requestIdleCallback(wookLoop);
}
打上标记后，需要在commitWork中根据不同的标记进行处理
PLACEMENT的直接添加到dom树中
UPDATE的需要更新props
DELETION的则进行删除操作

function commitWork(wipFiber) {
  if (!wipFiber) {
    return;
  }
  const domParent = fiber.parent.dom;
  if (fiber.effectTag === &quot;PLACEMENT&quot; &amp;&amp; fiber.dom) {
    domParent.appendChild(fiber.dom);
  } else if (fiber.effectTag === &quot;UPDATE&quot; &amp;&amp; fiber.dom) {
    updateDom(fiber.dom, fiber.base.props, fiber.props);
  } else if (fiber.effectTag === &quot;DELETION&quot;) {
    domParent.removeChild(fiber.dom);
  }

  commitWork(wipFiber.child);
  commitWork(wipFiber.sibling);
}
在updateDom中进行props的更新
function updateDom(dom, prevProps, nextProps) {
  // 以 “on” 开头的属性作为事件要特别处理
  // 移除旧的或者变化了的的事件处理函数
  Object.keys(prevProps)
    .filter((key) =&gt; key.startsWith(&quot;on&quot;))
    .filter((key) =&gt; !(key in nextProps) || prevProps[key] !== nextProps[key])
    .forEach((name) =&gt; {
      const eventType = name.toLowerCase().substring(2);
      dom.removeEventListener(eventType, prevProps[name]);
    });
  // 移除旧的属性
  Object.keys(prevProps)
    .filter((key) =&gt; key !== &quot;children&quot;)
    .filter((key) =&gt; !key.startsWith(&quot;on&quot;))
    .filter((key) =&gt; prevProps[key] !== nextProps[key])
    .forEach((name) =&gt; {
      dom[name] = &quot;&quot;;
    });
  // 添加或者更新属性
  Object.keys(nextProps)
    .filter((key) =&gt; key !== &quot;children&quot;)
    .filter((key) =&gt; !key.startsWith(&quot;on&quot;))
    .filter((key) =&gt; prevProps[key] !== nextProps[key])
    .forEach((name) =&gt; {
      dom[name] = nextProps[name];
    });
  // 添加新的事件处理函数
  Object.keys(nextProps)
    .filter((key) =&gt; key.startsWith(&quot;on&quot;))
    .filter((key) =&gt; prevProps[key] !== nextProps[key])
    .forEach((name) =&gt; {
      const eventType = name.toLowerCase().substring(2);
      dom.addEventListener(eventType, nextProps[name]);
    });
}
同时在createDom中进行逻辑的修改
function createDom(vdom) {
  const dom =
    vdom.type === &quot;TEXT_NODE&quot;
      ? document.createTextNode(&quot;&quot;)
      : document.createElement(vdom.type);

  updateDom(dom, {}, fiber.props);

  return dom;
}
## 函数组件
以一个简单的函数组件为例：
```js
function App(props) {
    return createElement(&quot;h1&quot;, null, &quot;Hellow &quot;, props.name);
}
const element = createElement(App, { name: &quot;world&quot; });
render(element, document.getElementById(&quot;root&quot;));
在performUnitOrWork中需要判断是否是函数组件
function performUnitOfWork(fiber) {
  fiber.type instanceof Function
    ? updateFunctionComponent(fiber)
    : updateHostComponent(fiber);

  if (fiber.child) {
    return fiber.child;
  }

  let nextFiber = fiber;
  while (nextFiber) {
    if (nextFiber.sibling) {
      return nextFiber.sibling;
    }
    nextFiber = nextFiber.parent;
  }
  return null;
}

function updateFunctionComponent(fiber) {
  reconcileChildren(fiber, [fiber.type(fiber.props)]);
}
function updateHostComponent(fiber) {
  if (!fiber.dom) {
    fiber.dom = createDom(fiber);
  }
  reconcileChildren(fiber, fiber.props.children);
}
因为函数组件是没有dom节点的
且函数组件的children来自函数的返回结果
所以需要改动commitWork中的逻辑
function commitWork(wipFiber) {
  if (!wipFiber) {
    return;
  }
  // 是函数组件时节点不存在 DOM，
  // 故需要遍历父节点以找到最近的有 DOM 的节点
  let domParentFiber = wipFiber.parent;
  while (!domParentFiber.dom) {
    domParentFiber = domParentFiber.parent;
  }
  const domParent = domParentFiber.dom;
  if (wipFiber.effectTag === &quot;PLACEMENT&quot; &amp;&amp; wipFiber.dom) {
    domParent.appendChild(wipFiber.dom);
  } else if (wipFiber.effectTag === &quot;UPDATE&quot; &amp;&amp; wipFiber.dom) {
    updateDom(wipFiber.dom, wipFiber.base.props, wipFiber.props);
  } else if (wipFiber.effectTag === &quot;DELETION&quot;) {
    commitDeletion(wipFiber, domParent);
  }

  commitWork(wipFiber.child);
  commitWork(wipFiber.sibling);
}

function commitDeletion(fiber, domParent) {
    // 如果是函数组件就没有DOM 需要继续向下遍历
  if (fiber.dom) {
    domParent.removeChild(fiber.dom);
  } else {
    commitDeletion(fiber.child, domParent);
  }
}
useState
案例：
function App(props) {
    const [count, setCount] = useState(0);
    return createElement(
      &quot;h1&quot;,
      { onClick: () =&gt; setCount((v) =&gt; v + 1) },
      &quot;Count: &quot;,
      count
    );
}
const element = createElement(App, {});
render(element, document.getElementById(&quot;root&quot;));
全局声明wipFiber变量表示当前的fiber
hookIndex来表示当前的hook序号
在wipFIber上声明hooks数组，用来依次存放hook
在updateFunctionCompoent中进行赋值
function updateFunctionComponent(fiber) {
  wipFiber = fiber;
  hookIndex = 0;
  wipFiber.hooks = [];
  const children = [fiber.type(fiber.props)];
  reconcileChildren(fiber, children);
}
useState的简单实现
function useState(initial) {
  const oldHook = wipFiber.base?.[hookIndex];
  const hook = {
    state: oldHook ? oldHook.state : initial,
    queue: [],
  };
  const actions = oldHook ? oldHook.queue : [];
  actions.forEach((action) =&gt; {
    // action可以是传入一个参数为state的函数
    hook.state = action instanceof Function ? action(hook.state) : action;
  });

  //setState将wipRoot重新赋值 触发渲染
  const setState = (action) =&gt; {
    hook.queue.push(action);
    wipRoot = {
      dom: currentRoot.dom,
      props: currentRoot.props,
      base: currentRoot,
    };
    nextUnitOfWork = wipRoot;
    deletions = [];
  };
  wipFiber.hooks.push(hook);
  hookIndex++;
  return [hook.state, setState];
}
