TypeScript/TS项目配置alias.content:
在 vite 中配置 alias(在 webpack 或者 babel 中配置也是同理)
💡注：需要下载 @types/node 才可以正常引入 path 和使用 __dirname
import { defineConfig } from &quot;vite&quot;;
import path from &quot;path&quot;;

export default defineConfig({
  resolve: {
    alias: [
      {
        find: &quot;@&quot;,
        replacement: path.resolve(__dirname, &quot;src&quot;),
      },
    ],
  },
});
配置完成后，会发现代码是可以正常运行的，但是在编辑器里会报错
import Login from *&quot;@/pages/Login*&quot;; 

// Cannot find module &#039;@/pages/Login&#039; or its corresponding type declarations.ts(2307)
解决方案：需要在 tsconfig.json 里的compilerOptions中加上 baseUrl 和 paths
{
  &quot;compilerOptions&quot;: {
    &quot;baseUrl&quot;: &quot;.&quot;,
    &quot;paths&quot;: {
      &quot;@/*&quot;: [&quot;src/*&quot;]
    }
  }
}

TypeScript/TypeScript-4.6-Beta更新.content:
允许在constructors的super前写代码
在JavaScript的类中引用this之前必须先调用super，TypeScript中也强制这点，但是更加严格，如果具有任何属性初始化的类在constructor的开头包含任何代码都会报错
class Base { }

class Derived extends Base {
  constructor() {
    console.log(&#039;123&#039;) // A &#039;super&#039; call must be the first statement in the constructor when a class contains initialized properties, parameter properties, or private identifiers
    super();
  }
}
新版本在检查方面变得宽松，可以让其他的代码在super之前执行，但是仍然会确保super会出现在引用this之前
如果在super前引用了this，会产生如下报错
// A &#039;super&#039; call must be the first statement in the constructor to refer to &#039;super&#039; or &#039;this&#039; when a derived class contains initialized properties, parameter properties, or private identifiers.(2376)
//&#039;super&#039; must be called before accessing &#039;this&#039; in the constructor of a derived class.(17009)
改进递归深度检查
对象类型的兼容基于它拥有的成员
interface Source {
    prop: string;
}

interface Target {
    prop: number;
}

function check(source: Source, target: Target) {
    target = source;
    // error!
    // Type &#039;Source&#039; is not assignable to type &#039;Target&#039;.
    //   Types of property &#039;prop&#039; are incompatible.
    //     Type &#039;string&#039; is not assignable to type &#039;number&#039;.
}
TypeScript中如果一个类型遇到一定的深度检查后似乎是无限拓展的，那就认为这些类型可能是兼容的
interface Source&lt;T&gt; {
    prop: Source&lt;Source&lt;T&gt;&gt;;
}

interface Target&lt;T&gt; {
    prop: Target&lt;Target&lt;T&gt;&gt;;
}

function check(source: Source&lt;string&gt;, target: Target&lt;number&gt;) {
    target = source;
}
通常情况是足够了，但是会有漏网之鱼：
因为y的嵌套比x要少，所以赋值操作应该是不成立的，但是在老的版本是不会报错的
新版本进一步提升了递归类型检查的能力，能够区分这里的两种情况，对于无限嵌套可以更加迅速地判断出来
interface Foo&lt;T&gt; {
    prop: T;
}

declare let x: Foo&lt;Foo&lt;Foo&lt;Foo&lt;Foo&lt;Foo&lt;string&gt;&gt;&gt;&gt;&gt;&gt;;
declare let y: Foo&lt;Foo&lt;Foo&lt;Foo&lt;Foo&lt;string&gt;&gt;&gt;&gt;&gt;;

x = y;
索引访问的推断改进
新版本的TypeScript可以正确推断出这些立即索引到一个映射对象类型的索引访问类型
TypeScript理解record.f(record.v)的调用是有效的，而之前的版本会报错，需要通过类型断言等方式来进行有效调用
 interface TypeMap {
    &quot;number&quot;: number;
    &quot;string&quot;: string;
    &quot;boolean&quot;: boolean;
}

type UnionRecord&lt;P extends keyof TypeMap&gt; = { [K in P]:
    {
        kind: K;
        v: TypeMap[K];
        f: (p: TypeMap[K]) =&gt; void;
    }
}[P];

function processRecord&lt;K extends keyof TypeMap&gt;(record: UnionRecord&lt;K&gt;) {
    record.f(record.v);
}

processRecord({
    kind: &quot;string&quot;,
    v: &quot;hello!&quot;,
    // &#039;val&#039; used to implicitly have the type &#039;string | number | boolean&#039;,
    // but now is correctly inferred to just &#039;string&#039;.
    f: val =&gt; {
        console.log(val.toUpperCase());
    }
})
相关参数的控制流分析
当kind为a的时候，paload的类型应该是number，当kind为b的时候，padyload的类型应该是string
现在TypeScript可以缩小依赖于其他参数的参数类型
type Func = (...args: [&quot;a&quot;, number] | [&quot;b&quot;, string]) =&gt; void;

const f1: Func = (kind, payload) =&gt; {
    if (kind === &quot;a&quot;) {
        payload.toFixed();  // &#039;payload&#039; narrowed to &#039;number&#039;
    }
    if (kind === &quot;b&quot;) {
        payload.toUpperCase();  // &#039;payload&#039; narrowed to &#039;string&#039;
    }
};

f1(&quot;a&quot;, 42);
f1(&quot;b&quot;, &quot;hello&quot;);
TypeScript追踪分析
TypeScript有一个--generateTrace选项来帮助识别一些耗时的类型编译工作，但是在现有的可视化工具中还是很难阅读
发布了@typescript/analyze-trace的工具来更容易理解这些信息，可以帮助分析TypeScript的构建性能问题
通用对象的解构会删除一些无法传播的成员
现在通过...rest来解构通用对象的时候，会删除不可解构的值以及对象中的方法
在新版本中，rest的类型是Omit&lt;T,&quot;someProperty&quot;|&quot;someMethod&quot;&gt;
class Thing {
    someProperty = 42;
    someMethod() {
        // ...
    }
}

function foo&lt;T extends Thing&gt;(x: T) {
    let { someProperty, ...rest } = x;

    // Used to work, is now an error!
    // Property &#039;someMethod&#039; does not exist on type &#039;Omit&lt;T, &quot;someProperty&quot; | &quot;someMethod&quot;&gt;&#039;.
    rest.someMethod();
}

TypeScript/TypeScript-4.7-4.9特性浅析.content:
4.9
satisfies操作符
TS有强大的推导能力能够自动地完成某些类型信息的推导
const palette = {
  red: [255, 0, 0],
  green: &quot;#00ff00&quot;,
  blue: [0, 0, 255]
};

// 其类型将被自动推导为：
interface Palette {
  red: number[];
  green: string;
  blue: number[];
}
由于是从值推导得到类型，而不是使用类型约束值，那么在提供了错误的值时，推导得到的类型信息也将出现问题
const palette = {
  red: [255, 0, 0],
  // typo
  grren: &#039;#00ff00&#039;,
  blue: [0, 0, 255],
};
为了避免这种问题，通常会使用显式地类型标注：
type Colors = &#039;red&#039; | &#039;green&#039; | &#039;blue&#039;;
type RGB = [number, number, number];

const palette: Record&lt;Colors, string | RGB&gt; = {
  red: [255, 0, 0],
  // × 不存在此属性
  grren: &#039;#00ff00&#039;,
  blue: [0, 0, 255],
};
看起来完成了非常精确的类型标注，但现在调用出现了类型错误：
palette.green.startsWith(&#039;#&#039;); // × 类型“string | RGB”上不存在属性“startsWith”
palette.red.startsWith(&#039;#&#039;); // × 类型“string | RGB”上不存在属性“startsWith”
在进行变量类型信息地标注时，其实是在告诉 TS 类型系统，这个变量的值必须完全符合这个类型，在后续使用这个变量时其类型信息会完全使用我们提供地类型信息，而不是其推导出的类型信息，即现在是让值完全符合类型，然后使用我们提供的类型信息
而实际需要的效果则是，让值符合类型的前提下，结合使用值推导出的类型信息：palette只需要满足类型约束，其键值类型不会使用 string | RGB ，而是仍然使用每个属性访问推导出的对应类型
而satisfies就是来支持这个功能的：
const palette = {
    red: [255, 0, 0],
    green: &quot;#00ff00&quot;,
    blue: [0, 0, 255]
} satisfies Record&lt;Colors, string | RGB&gt;;

// string
palette.green.startsWith(&#039;#&#039;); // √
// [number, number, number]
palette.red.find(); // √
// [number, number, number];
palette.blue.entries(); // √
单文件级别配置
单文件级别的 tsconfig 配置，使用 @ts-config value 的形式，如以下示例：
// @ts-strict 
// @ts-noUnusedLocals
// @ts-strictNullChecks
// @ts-noPropertyAccessFromIndexSignature false
对未列出属性的类型收窄增强
在面对联合类型时，经常使用类型守卫的方式来显式地提供类型信息，来帮助修正对应分支的类型控制流分析上下文
interface LoginUser {
  userId: string;
  invitor: string;
}

interface Visitor {
  visitorId: string;
  from: string;
}

function checkUser(user: LoginUser | Visitor): string {
  if (&#039;userId&#039; in user) {
    return user.invitor
  } else {
    return user.from;
  }
}
然而 in关键字在某些时候也存在着能力的不足
interface LoginUser {
  userId: string;
  invitor: string;
}

interface Visitor {
  visitorId: string;
  from: string;
}

function checkUser(info: { user: unknown }): string {
  const user = info.user;
  if (user &amp;&amp; typeof user === &quot;object&quot;) {
    if (&#039;userId&#039; in user &amp;&amp; typeof user.userId === &#039;string&#039;) {
      // Property &#039;userId&#039; does not exist on type &#039;object&#039;
      return user.userId; 
    }
  }
}
in操作符只会严格缩小到当前需要的检查类型，而 userId 并没有在 user类型上列出，所以 user 仍然只会是 object 类型
而在 4.9 版本，现在面对这种情况， in 操作符会将检查类型缩小到 object &amp; Record&lt;“userId”, unknown&gt; 类型，这样就能够支持未列出属性的类型守卫了
另外，4.9 版本现在也会约束 in 操作符的左侧必须是 string / number / symbol 类型，以及右侧必须是 object 类型
对 NaN 类型的相等检查
新增了错误使用等价判断方式的提示：
// 此表达式将始终返回 false，你是否指 Number.isNaN(value) ?
if(value === NaN) {}
4.8
交叉类型与联合类型的类型收窄增强
对 —strictNullChecks 进行了进一步增强，主要体现在联合类型与交叉类型，以及类型收窄地表现上
现在 unknown 和 {} | null | undefined 可以互相兼容
declare let v1: unknown;
declare let v2: {} | null | undefined;

v1 = v2;
// 此前会报错，因为认为 unknown 包含的类型信息更多
v2 = v1;
将使用 {} 的交叉类型，如 obj &amp; {} 直接简化为 obj 类型，前提是 obj 并非来自于泛型，且非 null / undefined
因为交叉类型要求同时满足两个类型，而只要 obj 不是 null / undefined 类型，就可以认为必定也符合 {} 类型，因此可以直接将 {} 从交叉类型中移除：
type T1 = {} &amp; string;  // string
type T2 = {} &amp; &#039;linbudu&#039;;  // &#039;linbudu&#039;
type T3 = {} &amp; object;  // object
type T4 = {} &amp; { x: number };  // { x: number }
type T5 = {} &amp; null;  // never
type T6 = {} &amp; undefined;  // never
NonNullable 实现会被更改为以下这种
type _NonNullable&lt;T&gt; = T extends null | undefined ? never : T;
type NonNullable&lt;T&gt; = T &amp; {};
模板字符串类型中的 infer 提取
当 infer 被约束为一个原始类型，那么它现在会尽可能将 infer 的类型信息推导到字面量类型的级别
// 此前为 number，现在为 &#039;100&#039;
type SomeNum = &quot;100&quot; extends `${infer U extends number}` ? U : never;

// 此前为 boolean，现在为 &#039;true&#039;
type SomeBool = &quot;true&quot; extends `${infer U extends boolean}` ? U : never;
绑定类型中的类型推导
泛型填充也会受到其调用方的影响
declare function chooseRandomly&lt;T&gt;(x: T,): T;

// Array&lt;string | number | boolean&gt;
const res1 = chooseRandomly([&quot;linbudu&quot;, 599, false]);
换一个方法：
declare function chooseRandomly&lt;T&gt;(x: T,): T;
​
// [string, number, boolean]
const [a, b, c] = chooseRandomly([&quot;linbudu&quot;, 599, false]);
一泛型填充方式被称为绑定模式。而在新版本中，禁用了基于绑定模式的类型推导，因为其对泛型的影响并不始终正确
declare function f&lt;T&gt;(x?: T): T;
​
// [any, any, any] 你咋知道我是个数组结构？？？
const [x, y, z] = f();
对象字面量值与数组字面量值的全等比较提示
const obj = {};
​
// 此语句始终将返回 false，因为 JavaScript 中使用引用地址比较对象，而非实际值
if(obj === {}){
  
}

const func = () =&gt; {};
​
// 此表达式将始终返回 true，你是否想要调用 func ？
if(func) { }
4.7
计算属性的类型控制流分析
在 4.7 版本以前， typeof obj[key] === “string” 成立后的语句块中，obj[key] 的类型并不会被收窄到 string
const key = Symbol();

const numberOrString = Math.random() &lt; 0.5 ? 42 : &quot;hello&quot;;

let obj = {
    [key]: numberOrString,
};

if (typeof obj[key] === &quot;string&quot;) {
    let str = obj[key].toUpperCase();
}
对象中的函数类型推导增强
这两个调用都是正常的，TypeScript 能够从 produce 函数的返回值推导出泛型参数 T 的类型，并应用到 consume 函数的入参类型中
declare function f&lt;T&gt;(arg: {
    produce: (n: string) =&gt; T,
    consume: (x: T) =&gt; void }
): void;

// Works
f({
    produce: () =&gt; &quot;hello&quot;,
    consume: x =&gt; x.toLowerCase()
});

// Works
f({
    produce: (n: string) =&gt; n,
    consume: x =&gt; x.toLowerCase(),
});
而以下几个例子在4.7版本之前就不行了：
在第一处，produce 的入参类型并没有成功地传递给返回值类型。而在第二、第三个，produce 函数的返回值类型没有从其内部推导得到，仍然是默认的 unknown 类型
f({
    produce: n =&gt; n,
    consume: x =&gt; x.toLowerCase(),
});

f({
    produce: function () { return &quot;hello&quot;; },
    consume: x =&gt; x.toLowerCase(),
});

f({
    produce() { return &quot;hello&quot; },
    consume: x =&gt; x.toLowerCase(),
});
泛型实例化表达式
假设要创建一个键类型为 string，键值类型为 Error 的 Map，通常会这么做
const errorMap: Map&lt;string, Error&gt; = new Map()
或者将这个 Map 类型抽离为一个类型别名：
type ErrorMapType = Map&lt;string, Error&gt;
但是两种做法都是在定义时的类型参数填充，且变量的类型是在实际调用时才确认的
而使用泛型实例化表达式，可以做到无需调用的情况下预先填充类型参数：
// 注意，这里不是类型别名
const ErrorMap = Map&lt;string, Error&gt;;

const errorMap = new ErrorMap();
一个更常见的场景是对接受泛型的函数按场景进行对应的实例化
function asFEEngineer&lt;T&gt;(value: T) {
    return { value };
};
这个函数只能确定是一个前端工程师，而不能确定其具体的方向
有了实例化表达式，可以通过预填充泛型参数的方式来实现不同场景的对应实例
const asMobile = asFEEngineer&lt;&quot;mobile&quot;&gt;;
const asNodeJs = asFEEngineer&lt;&quot;nodejs&quot;&gt;;
const asInfra = asFEEngineer&lt;&quot;infra&quot;&gt;;
每一个函数除了泛型参数已固定以外，和原本的函数完全一致
const mobileFEEngineer = asMobile(&quot;mobile&quot;);
由于实例化表达式的本质仍然是表达式，它也支持被作为 typeof 的输入
type StringBoxMaker = typeof asFEEngineer&lt;&quot;mobile&quot;&gt;;  // (value: &quot;mobile&quot;) =&gt; { value: &quot;mobile&quot; }
type ErrorMapConstructor = typeof Map&lt;string, Error&gt;;  // new () =&gt; Map&lt;string, Error&gt;
infer 的 extends 约束支持
以提取数组/元组的首个字符串类型成员为🌰
type FirstString&lt;T&gt; =
    T extends [infer S, ...unknown[]]
        ? S extends string ? S : never
        : never;

 // string
type A = FirstString&lt;[string, number, number]&gt;;

// &quot;hello&quot;
type B = FirstString&lt;[&quot;hello&quot;, number, number]&gt;;

// &quot;hello&quot; | &quot;world&quot;
type C = FirstString&lt;[&quot;hello&quot; | &quot;world&quot;, boolean]&gt;;

// never
type D = FirstString&lt;[boolean, number, number]&gt;;
新版本支持了 infer 关键字的 extends 约束能力，这一能力能够大大简化许多现存工具类型/类型体操实现的条件语句判断
type FirstString&lt;T&gt; =
    T extends [infer S extends string, ...unknown[]]
        ? S
        : never;

TypeScript/TypeScript中回调函数的参数类型.content:
现象
声明三个 inferface , 其中Worker 是 Person 的子类型， Programmer 是 Worker 的子类型
同时声明一个函数 main，参数是一个入参和出参类型都是 Worker的函数
interface Person {
  breath: () =&gt; void
}

interface Worker extends Person {
  work: () =&gt; void
}

interface Programmer extends Worker {
  code: () =&gt; void
}

const main = (callback: (args: Worker) =&gt; Worker) =&gt; { }

const test = (arg: Worker): Worker =&gt; {
  return arg
}

main(test)
如果传入的函数入参和出参类型都是 Worker，肯定是能通过类型校验的
但如果尝试一下修改入参和出参的类型，会发现：
入参是 Person ，而出参是 Programmer 的时候，类型校验也是可以通过的
即函数的入参可以是父类型，而出参则可以是子类型
原因
在入参的类型中，本质的问题是：如果 main 函数内调用 callback传入了 Worker，在 test 函数中使用的时候会不会有问题
如果 test 的参数类型是 Person ，调用 breath 方法，而 Worker 上是包含的，所以是不会有问题
反而如果test 的参数类型是 Programmer ，调用了 code 方法，但 Worker 上没有这个方法，就会产生错误
在出参的类型中，问题也是类似的：通过调用 callback 产生的返回值，在其上调用 Worker 的方法会不会有问题
很显然出参的类型必须包含 Worker 上的所有方法，假设在 main 函数中，通过 callback 函数生成的对象，调用了 breath 或者 work 方法，如果该对象的类型是 Person 则是没有 work 方法的，就会产生报错，而 Programmer 则包含了 Worker 上的所有方法，是不会有问题的

TypeScript/TypeScript实战小节.content:
常量类型在Array.includes中的报错
在开发中经常会声明一些枚举常量的配置
const TEST_CONFIG = {
  a: 1,
  b: 2,
} as const
在想要判断一个该类型的值是否是其中几个枚举值时，会通过Array.includes来判断
但是会发现这种写法有类型错误
const testValue = Math.ceil(Math.random() * 3) as typeof TEST_CONFIG[keyof typeof TEST_CONFIG]

[TEST_CONFIG.a, TEST_CONFIG.b].includes(testValue)
//  Argument of type &#039;1 | 2 | 3&#039; is not assignable to parameter of type &#039;1 | 2&#039;.
//  Type &#039;3&#039; is not assignable to type &#039;1 | 2&#039;.
最简单的是对数组使用as来类型断言
([TEST_CONFIG.a, TEST_CONFIG.b] as number[]).includes(testValue)
也可以自定义一个includes方法实现类型守卫等功能

function include&lt;T, P&gt;(arr: T[], target: unknown): target is T {
  return arr.includes(target as any);
}

TypeScript/TypeScript工具类型.content:
Partial
将一个类型的全部属性设置成可选的
interface Todo {
  title: string;
  description: string;
}

function updateTodo(todo: Todo, fieldsToUpdate: Partial&lt;Todo&gt;) {
  return { ...todo, ...fieldsToUpdate };
}

const todo1 = {
  title: &quot;organize desk&quot;,
  description: &quot;clear clutter&quot;,
};

const todo2 = updateTodo(todo1, {
  description: &quot;throw out trash&quot;,
});
原理
type Partial&lt;T&gt; = {
    [P in keyof T]?: T[P];
};
Required
和Partial相反，将类型的所有属性设置成必选的
interface Props {
  a?: number;
  b?: string;
}
const obj: Props = { a: 5 };
const obj2: Required&lt;Props&gt; = { a: 5 };
// Property &#039;b&#039; is missing in type &#039;{ a: number; }&#039; but required in type &#039;Required&lt;Props&gt;&#039;.
原理
type Required&lt;T&gt; = {
    [P in keyof T]-?: T[P];
};
Readonly
将类型的所有属性设置成只读的，不能进行访问
interface Todo {
  title: string;
}
const todo: Readonly&lt;Todo&gt; = {
  title: &quot;Delete inactive users&quot;,
};
todo.title = &quot;Hello&quot;;
// Cannot assign to &#039;title&#039; because it is a read-only property.
原理
type Readonly&lt;T&gt; = {
    readonly [P in keyof T]: T[P];
};
Record&lt;Keys, Type&gt;
构建一个对象类型，键的类型是Keys，值的类型是Type
可以将一个类型的属性映射到另外一个类型
interface CatInfo {
  age: number;
  breed: string;
}
type CatName = &quot;miffy&quot; | &quot;boris&quot; | &quot;mordred&quot;;
const cats: Record&lt;CatName, CatInfo&gt; = {
  miffy: { age: 10, breed: &quot;Persian&quot; },
  boris: { age: 5, breed: &quot;Maine Coon&quot; },
  mordred: { age: 16, breed: &quot;British Shorthair&quot; },
};
原理
type Record&lt;K extends keyof any, T&gt; = {
    [P in K]: T;
};
Exclude&lt;UnionType, ExcludedMembers&gt;
从UnionType中排除可以分配给ExcludedMembers的成员来构造类型
type T0 = Exclude&lt;&quot;a&quot; | &quot;b&quot; | &quot;c&quot;, &quot;a&quot;&gt;;
// type T0 = &quot;b&quot; | &quot;c&quot;
type T1 = Exclude&lt;&quot;a&quot; | &quot;b&quot; | &quot;c&quot;, &quot;a&quot; | &quot;b&quot;&gt;;
// type T1 = &quot;c&quot;
type T2 = Exclude&lt;string | number | (() =&gt; void), Function&gt;;
// type T2 = string | number
原理
type Exclude&lt;T, U&gt; = T extends U ? never : T;
Extract&lt;Type, Union&gt;
和Exclude相反，是从Type中提取可以分配给Union的成员来构造类型
type T0 = Extract&lt;&quot;a&quot; | &quot;b&quot; | &quot;c&quot;, &quot;a&quot; | &quot;f&quot;&gt;;  
// type T0 = &quot;a&quot;
type T1 = Extract&lt;string | number | (() =&gt; void), Function&gt;;    
// type T1 = () =&gt; void
原理
type Extract&lt;T, U&gt; = T extends U ? T : never;
Pick&lt;Type, Keys&gt;
从Type中选取属性集合Keys来构造一个类型
interface Todo {
  title: string;
  description: string;
  completed: boolean;
}
type TodoPreview = Pick&lt;Todo, &quot;title&quot; | &quot;completed&quot;&gt;;
const todo: TodoPreview = {
  title: &quot;Clean room&quot;,
  completed: false,
};

原理
type Pick&lt;T, K extends keyof T&gt; = {
    [P in K]: T[P];
};
Omit&lt;Type, Keys&gt;
Omit与Pick相反，是删除keys来构造一个属性
interface Todo {
  title: string;
  description: string;
  completed: boolean;
  createdAt: number;
}
type TodoPreview = Omit&lt;Todo, &quot;description&quot;&gt;;
const todo: TodoPreview = {
  title: &quot;Clean room&quot;,
  completed: false,
  createdAt: 1615544252770,
};
原理
type Omit&lt;T, K extends keyof any&gt; = Pick&lt;T, Exclude&lt;keyof T, K&gt;&gt;;
NonNullable
去除类型中的null和undefined
type T0 = NonNullable&lt;string | number | undefined&gt;;
// type T0 = string | number
type T1 = NonNullable&lt;string[] | null | undefined&gt;;
// type T1 = string[]
原理
type NonNullable&lt;T&gt; = T extends null | undefined ? never : T;
Parameters
获取函数类型Type的参数来构造一个元祖类型
declare function f1(arg: { a: number; b: string }): void;
type T0 = Parameters&lt;() =&gt; string&gt;;
// type T0 = []
原理
type Parameters&lt;T extends (...args: any) =&gt; any&gt; = T extends (...args: infer P) =&gt; any ? P : never;
ConstructorParameters
从构造函数的类型中构造一个元组或数组类型
type T2 = ConstructorParameters&lt;RegExpConstructor&gt;;
// type T2 = [pattern: string | RegExp, flags?: string]
原理
type ConstructorParameters&lt;T extends abstract new (...args: any) =&gt; any&gt; = T extends abstract new (...args: infer P) =&gt; any ? P : never;
ReturnType
构建一个由函数Type的返回类型组成的类型
declare function f1(): { a: number; b: string };
type T0 = ReturnType&lt;() =&gt; string&gt;;
//  type T0 = string
原理
type ReturnType&lt;T extends (...args: any) =&gt; any&gt; = T extends (...args: any) =&gt; infer R ? R : any;

基础/伪元素.content:
empty
:empty代表没有子元素的元素
// css
div {
  height: 20px;
}
div:empty {
  background: red;
}

// html 
&lt;div&gt;&lt;/div&gt; &lt;!-- 生效 --&gt;
&lt;div&gt;content&lt;/div&gt;
first-child
:first-child表示一组兄弟元素的第一个元素
// css
p:first-child {
  color: lime;
}

// html
&lt;div&gt;
  &lt;p&gt;This text is selected!&lt;/p&gt;
  &lt;p&gt;This text isn&#039;t selected.&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;
  &lt;h2&gt;This text isn&#039;t selected: it&#039;s not a `p`.&lt;/h2&gt;
  &lt;p&gt;This text isn&#039;t selected.&lt;/p&gt;
&lt;/div&gt;
first-of-type
与 :first-child类似，表示一组兄弟元素中其类型的第一个元素，但不会管其在兄弟内的位置如何
// css
p:first-of-type {
  color: red;
}

//html
&lt;h2&gt;Heading&lt;/h2&gt;
&lt;p&gt;Paragraph 1&lt;/p&gt; // red
&lt;p&gt;Paragraph 1&lt;/p&gt;
last-child
:last-child表示父元素的最后一个子元素
// css
li:last-child {
  background-color: lime;
}
// html
&lt;ul&gt;
  &lt;li&gt;此元素背景色不是lime&lt;/li&gt;
  &lt;li&gt;我的也不是lime。&lt;/li&gt;
  &lt;li&gt;我的才是lime!&lt;/li&gt;
&lt;/ul&gt;
last-of-type
:last-of-type表示在子元素列表中最后一个给定类型的元素，也会包括子元素的最后一个子元素以此类推
// css
p em:last-of-type {
  color: lime;
}

// html
&lt;p&gt;
  &lt;em&gt;我没有颜色 :(&lt;/em&gt;&lt;br&gt;
  &lt;strong&gt;我没有颜色 :(&lt;/strong&gt;&lt;br&gt;
  &lt;em&gt;我有颜色 :D&lt;/em&gt;&lt;br&gt;
