基础/常用手写.content:
异步并发控制
单方法处理
const limitFn = (fn, limit) =&gt; {
  let count = 0;
  const queue = [];

  const run = () =&gt; {
    if (!queue.length || count &gt;= limit) {
      return;
    }

    count++;

    const { args, resolve, reject } = queue.shift();

    fn(...args)
      .then(resolve)
      .catch(reject)
      .finally(() =&gt; {
        count--;
        run();
      });
  };

  return (...args) =&gt;
    new Promise((resolve, reject) =&gt; {
      queue.push({ args, resolve, reject });
      run();
    });
};
批量版本
工人池模式
async function poolLimit(tasks, limit) {
  const result = [];
  const queue = tasks.map((fn, index) =&gt; ({ fn, index }));

  const coreWork = async () =&gt; {
    const { fn, index } = queue.shift();
    result[index] = await fn();

    if (queue.length) {
      await coreWork();
    }
  };

  await Promise.all(
    Array.from({ length: Math.min(limit, tasks.length) }, coreWork),
  );

  return result;
}
递归版本
async function poolLimit(tasks, limit) {
  const result = [];
  let index = 0;
  let running = 0;

  return new Promise((resolve) =&gt; {
    const run = () =&gt; {
      if (index === tasks.length &amp;&amp; !running) {
        resolve(result);
      }

      while (running &lt; limit &amp;&amp; index &lt; tasks.length) {
        running++;
        const i = index++;
        tasks[i]().then((res) =&gt; {
          result[i] = res;
          running--;
          run();
        });
      }
    };

    run();
  });
}
标签分类
单标签版本
// const data = [
//   {
//     tag: &quot;a&quot;,
//     value: 1,
//   },
//   {
//     tag: &quot;b&quot;,
//     value: 2,
//   },
//   {
//     tag: &quot;a&quot;,
//     value: 3,
//   },
// ];
const main = (origin) =&gt; {
  const result = {};
  origin.forEach((item) =&gt; {
    if (!result[item.tag]) {
      result[item.tag] = [];
    }
    result[item.tag].push(item.value);
  });
  return result
};
多标签版本
// 输入数据：[
//   {
//     name: 1,
//     tags: [&quot;a&quot;, &quot;b&quot;,],
//   },
//   {
//     name: 2,
//     tags: [&quot;a&quot;, &quot;c&quot;],
//   },                     
//   {
//     name: 3,
//     tags: [&quot;a&quot;, &quot;c&quot;],
//   },
//   {
//     name: 4,
//     tags: [&quot;b&quot;, &quot;c&quot;],
//   },
// ];

// 输出格式：
// [{
//   tag:&#039;&#039;,
//   list:[],
//   children:[],
// }]
const main = (origin) =&gt; {
  const result = [];

  origin.forEach((originItem) =&gt; {
    let current = result;

    originItem.tags.forEach((tag, index) =&gt; {
      const isLastTag = index === originItem.tags.length - 1;
      const currentItem = current.find((i) =&gt; i.tag === tag);

      if (isLastTag) {
        if (currentItem) {
          currentItem.list.push(originItem);
        } else {
          current.push({
            tag,
            list: [originItem],
            children: [],
          });
        }
      } else {
        if (currentItem) {
          current = currentItem.children;
        } else {
          const newChildren = [];
          current.push({ tag, list: [], children: newChildren });
          current = newChildren;
        }
      }
    });
  });

  return result;
};

