instanceof
const myInstanceof = (a, b) =&gt; {
  if (!a || typeof a !== &quot;object&quot; &amp;&amp; typeof a !== &quot;function&quot;) {
    return false;
  }

  const target = b.prototype;
  let proto = Object.getPrototypeOf(a)

  while (proto) {
    if (proto === target) {
      return true;
    }
    proto = Object.getPrototypeOf(proto)
  }

  return false;
};
new
const myNew = (Construct, ...args) =&gt; {
  const obj = Object.create(Construct.prototype);
  const newObj = Construct.apply(obj, args);

  if (newObj &amp;&amp; typeof newObj === &quot;object&quot;) {
    return newObj;
  }

  return obj;
};
Object.create
const myCreate = (proto) =&gt; {
  function F() {}
  F.prototype = proto;

  const obj = new F();

  if (proto === null) {
    Object.setPrototypeOf(obj, null);
  }

  return obj;
};

call
const myCall = (context, ...args) =&gt; {
  context = context || window;
  const tempField = Symbol();
  context[tempField] = this;
  const result = context[tempField](...args)
  delete context[tempField]
  return result
};
防抖节流
const throttle = (fn, delay) =&gt; {
  let flag = false;

  return (...args) =&gt; {
    if (flag) return;

    fn.call(this, ...args);
    flag = true;

    setTimeout(() =&gt; {
      flag = false;
    }, delay);
  };
};

const debounce = (fn, delay) =&gt; {
  let timer = null;

  return (...args) =&gt; {
    clearTimeout(timer);
    timer = setTimeout(() =&gt; {
      fn.call(this, ...args);
    }, delay);
  };
};

基础/浅入浅出tailwindcss.content:
是啥
tailwindcss本质上是一个postcss插件，在它的规则下写类名就可以自动生成相应的样式，简单来说就是提供了一堆开箱即用的原子化类名。

开发中的index.tsx

&lt;div className=&quot;flex justify-between items-center&quot;&gt;

打包后的index.css

.flex {
  display: flex;
}
.items-center {
  align-items: center;
}
.justify-between {
  justify-content: space-between;
}
为啥要用
更小的构建体积
一个dom元素对应一个类名的样式编写方式，会造成很多的重复样式代码。
如下🌰：在打包后的样式产物里，display: flex会出现两次。
.a {
  display: flex;
  justify-content: space-between;
}

.b {
  display: flex;
  justify-content: space-around;
}
但是通过原子化的样式编写方式，只会出现三个原子类名。
即使在100个地方使用了display:flex，最终的产物里也只会有flex这一个类名。
.flex {
  display: flex;
}
.justify-between {
  justify-content: space-between;
}
.justify-around {
  justify-content: space-around;
}
为了解决样式冲突而使用的嵌套语法+css module的方案，对样式文件的体积也是一种考验。

index.tsx

&lt;div className={style.content}&gt;
  &lt;div className={style.header}&gt;
    &lt;div className={style.left}&gt;
      &lt;div className={style.title}&gt;title&lt;/div&gt;
      &lt;div className={style.content}&gt;content&lt;/div&gt;
    &lt;/div&gt;
    &lt;div className={style.right}&gt; right&lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;

style.module.scss

.content {
  .header {
    .left {
      .title {
        display: flex;
      }

      .content {
        color: red;
      }
    }

    .right {
      line-height: 18px;
    }
  }
}

样式产物

.content___XZmmG .header___yuXTB .left___9v2w5 .title___bIYKs {
  display: flex;
}
.content___XZmmG .header___yuXTB .left___9v2w5 .content___XZmmG {
  color: red;
}
.content___XZmmG .header___yuXTB .right___UQlJn {
  line-height: 0.48rem;
}
更快的开发/维护效率

代码量
首先从编写的代码量上进行论证，一个原子化的类名肯定比它对应的具体样式要简略得多。
特别是一些简单的dom元素场景，只有几个小样式还得纠结下到底用什么类名，而原子化再也不用担心取名问题。

// 原子化CSS方案
&lt;div className=&quot;flex justify-between items-center&quot;&gt;

&lt;div className=&quot;m-4&quot;&gt;

// 常规方案
import style from &#039;./style.module.scss&#039;

&lt;div className={style.flex} &gt;

&lt;div className={style.margin} &gt;

.margin{
    margin: 16px;
}

.flex{
    display: flex;
    justify-content: space-between;
    align-items: center;
}

文件切换
无需切换上下文，原子化样式仅在tsx文件中就能完成整个需求的开发。
特别是阅读其他人代码的时候，不仅在tsx和scss之间来回切换，遇到一堆.title、.content的时候还得看它的爸爸是谁，它的爷爷是谁？？？
维护成本
css module里html和css的层级结构基本都是一致的，当dom元素需要跨层级的调整时，都得同步更改css文件的格式，特别是删除等操作，基本不会同步删除相应的样式，也不知道这个删了会不会有问题，导致样式文件难以维护；而原子化的样式跟着标签直接走就行了，不需要其他的心智负担。

