基础/浅析Promise实现.content:
浅析Promise实现
Promise构造函数的参数executor方法是同步执行的
then的回调会异步执行，实际会被放置到微任务队列中，并在执行完一个宏任务后清空队列，所以会比setTimeout的回调优先执行
class Promise {
  constructor(executor) {
    this.value = undefined;
    this.reason = undefined;
    this.status = &quot;pending&quot;;

    const resolve = (value) =&gt; {
        this.status = &quot;fulfilled&quot;;
        this.value = value;
    };

    const reject = (reason) =&gt; {
        this.status = &quot;rejected&quot;;
        this.reason = reason;
    };

    try {
      executor(resolve, reject);
    } catch (e) {
      reject(e);
    }
  }

  then(thenable, catchable) {
    if (this.status === &#039;fulfilled&#039;) {
      	// 模拟异步
        setTimeout(() =&gt; {
            thenable(this.value);
        });
    }

    if (this.status === &#039;rejected&#039;) {
        setTimeout(() =&gt; {
          catchable(this.reason);
        });
    }
  }
}
Promise支持链式调用，所以then其实返回的是一个Promise实例
如果then的回调函数返回值是一个Promise实例，则会执行其then方法
其他情况则直接把返回值给resolve掉
class Promise {
  // ...
  then(thenable) {
     return new MyPromise((resolve, reject) =&gt; {
       setTimeout(() =&gt; {
           try {
              const result = thenable(this.data);
              if (result instanceof Promise) {
                  result.then(d =&gt; {
                      resolve(d)
                  }, err =&gt; {
                      reject(err);
                  })
              }
              else {
                  resolve(result);
              }
          }
          catch (err) {
              reject(err);
          }
        });
    })
  }
}
Promise的resolve可能异步执行的，且一个Promise实例可以调用多次then方法：
const promise = new Promise((resolve) =&gt; {
  setTimeout(() =&gt; {
    resolve(1);
  }, 1000);
});
promise.then((res) =&gt; console.log(res));
promise.then((res) =&gt; console.log(res));
所以then函数中需要根据状态来判断是否被resolve或者reject
可以通过一个数组来存储相应的回调函数，在改变状态的时候依次执行
class Promise {
  constructor(executor) {
    this.status = &quot;pending&quot;;
    this.thenables = [];
    this.value = undefined;

    const resolve = data =&gt; {
      	this.status = &#039;fulfilled&#039;;
        this.value = data;
        thenables.forEach(fn =&gt; fn(data));
    }
    // ...
	}
  then(thenable){
    if (this.status === &#039;fulfilled&#039;) {
       // ...
    }
    else {
        this.thenables.push(thenable);
    }
  }
}
最终完整实现版本：

const PENDING = &quot;pending&quot;,
RESOLVED = &quot;resolved&quot;,
REJECTED = &quot;rejected&quot;

class MyPromise {
changeStatus(newStatus, newValue, queue) {
    if (this.status !== PENDING) {
        return;
    }
    this.status = newStatus;
    this.value = newValue;
    queue.forEach(handler =&gt; handler(newValue));
}

constructor(executor) {
    this.status = PENDING;
    this.value = undefined;
    this.thenables = [];
    this.catchables = [];

    const resolve = data =&gt; {
        this.changeStatus(RESOLVED, data, this.thenables);
    }

    const reject = reason =&gt; {
        this.changeStatus(REJECTED, reason, this.catchables);
    }
    try {
        executor(resolve, reject)
    }
    catch (err) {
        reject(err);
    }
}

settleHandle(handler, immediatelyStatus, queue) {
    if (typeof handler !== &quot;function&quot;) {
        return;
    }
    if (this.status === immediatelyStatus) {
        setTimeout(() =&gt; {
            handler(this.value);
        }, 0);
    }
    else {
        queue.push(handler);
    }
}

linkPromise(thenalbe, catchable) {
    function exec(data, handler, resolve, reject) {
        try {
            const result = handler(data);
            if (result instanceof MyPromise) {
                result.then(d =&gt; {
                    resolve(d)
                }, err =&gt; {
                    reject(err);
                })
            }
            else {
                resolve(result);
            }
        }
        catch (err) {
            reject(err);
        }
    }

    return new MyPromise((resolve, reject) =&gt; {
        this.settleHandle(data =&gt; {
            exec(data, thenalbe, resolve, reject);
        }, RESOLVED, this.thenables)

        this.settleHandle(reason =&gt; {
            exec(reason, catchable, resolve, reject);
        }, REJECTED, this.catchables)
    })
}

then(thenable, catchable) {
    return this.linkPromise(thenable, catchable);
}

catch(catchable) {

    return this.linkPromise(undefined, catchable);
}


static all(proms) {
    return new Promise((resolve, reject) =&gt; {
        const results = proms.map(p =&gt; {
            const obj = {
                result: undefined,
                isResolved: false
            }
            p.then(data =&gt; {
                obj.result = data;
                obj.isResolved = true;
                const unResolved = results.filter(r =&gt; !r.isResolved)
                if (unResolved.length === 0) {
                    resolve(results.map(r =&gt; r.result));
                }
            }, reason =&gt; {
                reject(reason);
            })
            return obj;
        })
    })
}

static race(proms) {
    return new Promise((resolve, reject) =&gt; {
        proms.forEach(p =&gt; {
            p.then(data =&gt; {
                resolve(data);
            }, err =&gt; {
                reject(err);
            })
        })
    })
}

static resolve(data) {
    if (data instanceof MyPromise) {
        return data;
    }
    else {
        return new MyPromise(resolve =&gt; {
            resolve(data);
        })
    }
}

static reject(reason) {
    return new MyPromise((_resolve, reject) =&gt; {
        reject(reason);
    })
}
}

