快排
function main(arr) {
  if (arr.length &lt;= 1) {
    return arr;
  }

  const _partition = (left, right) =&gt; {
    const standard = arr[right];
    let activeIdx = left;

    for (let i = activeIdx; i &lt; right; i++) {
      if (arr[i] &lt; standard) {
        [arr[i], arr[activeIdx]] = [arr[activeIdx], arr[i]];
        activeIdx++;
      }
    }

    [arr[activeIdx], arr[right]] = [arr[right], arr[activeIdx]];

    return activeIdx
  };

  const _sort = (left, right) =&gt; {
    if (left &lt; right) {
      const middleIdx = _partition(left, right);
      _sort(left, middleIdx - 1);
      _sort(middleIdx + 1, right);
    }
  };

  _sort(0, arr.length - 1);

  return arr;
}
两数之和
给定一个整数数组 nums 和一个目标值 target，找出数组中和为目标值的两个整数的下标
const main = (arr, target) =&gt; {
