}
泰波那契数
T0 = 0, T1 = 1, T2 = 1, 且在 n &gt;= 0 的条件下 Tn+3 = Tn + Tn+1 + Tn+2
给你整数 n，请返回第 n 个泰波那契数 Tn 的值
// 递归
function main(n, cache = {}) {
  if (n === 0 || n === 1) {
    return n;
  }

  if (n === 2) {
    return 1;
  }

  if (cache[n]) {
    return cache[n];
  }

  cache[n] = main(n - 1, cache) + main(n - 2, cache) + main(n - 3, cache);
  return cache[n];
}

// 动态规划
function main(n) {
  const list = [];
  list[0] = 0;
  list[1] = 1;
  list[2] = 1;

  for (let i = 3; i &lt;= n; i++) {
    list[i] = list[i - 1] + list[i - 2] + list[i - 3];
  }

  return list[n];
}

// 滚动变量
function main(n) {
  if (n === 0 || n === 1) {
    return n;
  }

  if (n === 2) {
    return 1;
  }

  let a = 0,
    b = 1,
    c = 1;

  for (let i = 3; i &lt;= n; i++) {
    const next = a + b + c;
    a = b;
    b = c;
    c = next;
  }

  return c;
}

不同路径
一个机器人位于一个 m x n 网格的左上角 ，每次只能向下或者向右移动一步
机器人试图达到网格的右下角，总共有多少条不同的路径
// 普通版本
function main(m, n) {
  const array = new Array(m).fill(new Array(n).fill(0));

  for (let i = 0; i &lt; m; i++) {
    array[i][0] = 1;
  }

  for (let j = 0; j &lt; n; j++) {
    array[0][j] = 1;
  }

  for (let i = 1; i &lt; m; i++) {
    for (let j = 1; j &lt; n; j++) {
      array[i][j] = array[i - 1][j] + array[i][j - 1];
    }
  }

  return array[m - 1][n - 1];
}

// 滚动数组版本
function main(m, n) {
  const f = new Array(n).fill(1);
  for (let i = 1; i &lt; m; i++) {
    for (let j = 1; j &lt; n; j++) {
      f[j] += f[j - 1];
    }
  }
  return f[n - 1];
}
最长递增子序列
给你一个整数数组 input ，找到其中最长严格递增子序列的长度
function main(input) {
  if (!input.length) return 0;

  const list = new Array(input.length).fill(1);
  let maxLength = 1;
  for (let i = 1; i &lt; input.length; i++) {
    for (let j = 0; j &lt; i; j++) {
      if (input[j] &lt; input[i]) { 
        list[i] = Math.max(list[i], list[j] + 1);
      }
    }
    maxLength = Math.max(list[i], maxLength);
  }
  return maxLength;
}
数组中的第 K 个最大元素
给定整数数组 nums 和整数 k，请返回数组中第 k 个最大的元素
function main(input, target) {
  const _helper = (left, right) =&gt; {
    if (left === right) {
      return input[left];
    }

    const cur = input[right];
    let index = left;
    for (let i = index; i &lt; right; i++) {
      if (input[i] &gt; cur) {
        if (i !== index) {
          [input[i], input[index]] = [input[index], input[i]];
        }
        index++;
      }
    }
    [input[index], input[right]] = [input[right], input[index]];

    if (index + 1 === target) {
      return input[index];
    }

    if (index &lt; target) {
      return _helper(index + 1, right);
    } else {
      return _helper(left, index - 1);
    }
  };

  return _helper(0, input.length - 1);
}
