插件工具包
@rollup/pluginutils : 插件常用的工具方法
createFilter
传入 include 和 exclude 来得到一个筛选方法，用于确定是否需要操作某些模块
import { createFilter } from &#039;@rollup/pluginutils&#039;;

export default function plugin(options = {}) {
 const filter = createFilter(options.include, options.exclude});
  return {
    transform(code, id) {
      if (!filter(id)) return;
      // proceed with the transformation...
    }
  };
}
normalizePath
可以将路径分隔符转换成正斜杠
import { normalizePath } from &#039;@rollup/pluginutils&#039;;

normalizePath(&#039;foo\\bar&#039;); // &#039;foo/bar&#039;
normalizePath(&#039;foo/bar&#039;); // &#039;foo/bar&#039;
addExtension
如果 id 没有文件拓展名则进行添加，默认是 .js
import { addExtension } from &#039;@rollup/pluginutils&#039;;

export default function plugin(options = {}) {
  return {
    resolveId(code, id) {
      id = addExtension(id); // `foo` -&gt; `foo.js`, `foo.js` -&gt; `foo.js`
      id = addExtension(id, &#039;.myext&#039;); // `foo` -&gt; `foo.myext`, `foo.js` -&gt; `foo.js`
    }
  };
}

工具链/Rollup核心功能配置.content:
external

(string | RegExp)[] | RegExp | string | (id: string, parentId: string, isResolved: boolean) =&gt; boolean

可以传入字符串、正则，或者一个返回 boolean 的方法，参数为模块的 id 、执行导入的模块 id ，以及该 id 是否已经被解析
import path from &#039;path&#039;;
export default {
  external: [
    &#039;some-externally-required-library&#039;,
    path.resolve( __dirname, &#039;src/some-local-file-that-should-not-be-bundled.js&#039; ),
    /node_modules/
  ]
};
会将相应的文件保留在打包之外。如果想排除第三方库的内容，需要借助 @rollup/plugin-node-resolve等插件
// input:
import a from &quot;./a&quot;;
console.log(a);

// output: without external
const a = 123;
console.log(a);

// output: with external: [path.resolve(__dirname, &quot;src/a.js&quot;)],
import a from &#039;./a.js&#039;;
console.log(a);
如果是 iife 或 umd 的打包格式，需要通过 output.globals 等选项来提供全局变量名称来替换外部导入
import resolve from &quot;@rollup/plugin-node-resolve&quot;;

export default {
  input: &quot;./src/index.js&quot;,
  output: {
    file: &quot;./dist/index.js&quot;,
    format: &quot;iife&quot;,
    globals: {
      &quot;lodash-es&quot;: &quot;test&quot;,
    },
  },
  plugins: [resolve()],
  external: [&quot;lodash-es&quot;],
};

// input:
import { isEmpty } from &quot;lodash-es&quot;;
console.log(isEmpty({}));

// output:
(function (lodashEs) {
	&#039;use strict&#039;;
	console.log(lodashEs.isEmpty({}));
})(test);
input

string | string [] | { [entryName: string]: string }

打包的入口文件。如果是一个数组或者对象，会打包到分别的输出 chunk 中
如果没有填写 output.file ，会依据 output.entryFileNames 来生成 chunk 名字
如果是对象形式， 输出文件名的 [name] 部分是对象属性的名称
export default {
  input: {
    a: &#039;src/a.js&#039;,
    b: &#039;src/b.js&#039;
  },
  output: {
    entryFileNames: &#039;entry-[name].js&#039; // entry-a.js entry-b.js
  }
};
而对于数组形式的话，则是入口的文件名
export default {
  input: [&quot;./src/a.js&quot;, &quot;./src/b.js&quot;],
  output: {
    entryFileNames: &quot;entry-[name].js&quot;, // entry-a.js entry-b.js
  },
};
output.dir

string

指定生成 chunk 的目录。在生成多个 chunk 的时候使用，否则使用 file 选项即可
output.file

string

输出的文件，在适用的时候也可以生成 sourcemap ，只能在生成不大于一个 chunk 的时候使用
output.format

string = &quot;es&quot;

打包文件的生成格式，包括

amd： Asynchronous Module Definitioe，现在使用较少
cjs： CommonJS ，可以运行在 Node
es：ES module，可以通过 &lt;script type=&quot;module&quot;&gt; 运行在现代浏览器里
iife： 立即执行函数，可以直接在 &lt;script&gt; 里执行
umd：通用的模块定义，支持多种引入方式
system： SystemJS 加载器的原生格式

output.globals

{ [id: string]: string } | ((id: string) =&gt; string)

在 umd、iife的产物中使用了 external imports ，必须使用该选项来指定相应的名称
例：在项目中 import $ from &#039;jquery&#039;，配置文件中把jquery放入到external里
// rollup.config.js
export default {
  external: [&#039;jquery&#039;],
  output: {
    format: &#039;iife&#039;,
    name: &#039;MyBundle&#039;,
    globals: {
      jquery: &#039;$&#039;
    }
  }
};

// output:
var MyBundle = (function ($) {
  // ...
}($));
output.name

string

对于 iife 、 umd 的输出格式需要指定全局变量名，这样其他的 scripts 就可以通过该变量名称来访问该包的导出内容
// rollup.config.js
export default {
  ...,
  output: {
    file: &#039;bundle.js&#039;,
    format: &#039;iife&#039;,
    name: &#039;MyBundle&#039;
  }
};

// output:
var MyBundle = (function () {...})
output.plugins

OutputPlugin | (OutputPlugin | void)[]

针对该output添加插件，且不是每个插件都可以使用，仅限于使用在 bundle.gengerate 或 bundle.write 期间运行的钩子的插件，即在 rollup 完成主要分析之后
import { terser } from &#039;rollup-plugin-terser&#039;;

export default {
  input: &#039;main.js&#039;,
  output: [
    {
      file: &#039;bundle.js&#039;,
      format: &#039;es&#039;
    },
    {
      file: &#039;bundle.min.js&#039;,
      format: &#039;es&#039;,
      plugins: [terser()]
    }
  ]
};
plugins

Plugin | (Plugin | void)[]

注册插件，如果是 falsy 的插件会直接被忽略
import resolve from &#039;@rollup/plugin-node-resolve&#039;;
import commonjs from &#039;@rollup/plugin-commonjs&#039;;

const isProduction = process.env.NODE_ENV === &#039;production&#039;;

export default (async () =&gt; ({
  input: &#039;main.js&#039;,
  plugins: [resolve(), commonjs(), isProduction &amp;&amp; (await import(&#039;rollup-plugin-terser&#039;)).terser()],
  output: {
    file: &#039;bundle.js&#039;,
    format: &#039;cjs&#039;
  }
}))();

工具链/Vite实战小结.content:
区分开发和生产环境
在打包的时候，将产物的静态资源路径替换成cdn路径前缀
通过process.env.NODE_ENV是否是production来判断，开发的时候环境变量可能为空，导致开发路径不符合预期
{
    base: process.env.NODE_ENV === &quot;production&quot; ? CDN_URL_PREFIX : &quot;/&quot;,
}
cdn插件
不打包react这些第三方库，直接通过相应的cdn链接来引入
解析需要处理的模块配置，读取其在node_modules里的版本，通过rollup-plugin-external-globals插件来转换打包代码，然后通过vite提供的transform钩子插入script标签来引入cdn资源
import {
  UserConfig,
  PluginOption,
} from &quot;vite&quot;;
import externalGlobals from &quot;rollup-plugin-external-globals&quot;;

const prodUrl = &quot;https://xxxxxx/:name@:version/:path&quot;;

const modules: vitePluginCDNOption[&quot;modules&quot;] = [
  {
    name: &quot;react&quot;,
    var: &quot;React&quot;,
  },
  {
    name: &quot;react-dom&quot;,
    var: &quot;ReactDOM&quot;,
  },
  {
    name: &quot;history&quot;,
    var: &quot;HistoryLibrary&quot;,
  },
  {
    name: &quot;react-router&quot;,
    var: &quot;ReactRouter&quot;,
  },
  {
    name: &quot;react-router-dom&quot;,
    var: &quot;ReactRouterDOM&quot;,
  },
];

const getVersionInNodeModules = (name, pathToNodeModules = process.cwd()) =&gt; {
  const packageJson = &quot;package.json&quot;;
  try {
    return require(path.join(
      pathToNodeModules,
      &quot;node_modules&quot;,
      name,
      packageJson
    )).version;
  } catch (e) {
    return null;
  }
};

const vitePluginCDN: (option: vitePluginCDNOption) =&gt; PluginOption = (
  option: vitePluginCDNOption
) =&gt; {
  const { modules, prodUrl } = option;
  return {
    name: &quot;vite-plugin-cdn&quot;,
    enforce: &quot;post&quot;,
    transformIndexHtml: {
      config: () =&gt; {
        const userConfig: UserConfig = {
          build: {
            rollupOptions: {},
          },
        };
        const externalMap = {};
        modules.forEach((module) =&gt; {
          externalMap[module.name] = module.var;
        });
        userConfig.build.rollupOptions = {
          plugins: [externalGlobals(externalMap)],
        };
        return userConfig;
      },
      transform: async (html) =&gt; {
        return {
          html,
          tags: modules.map(({ name, path }) =&gt; {
            const version = getVersionInNodeModules(name);
            return {
              tag: &quot;script&quot;,
              attrs: {
                defer: &quot;defer&quot;,
                src: prodUrl
                  .replace(&quot;:name&quot;, name)
                  .replace(&quot;:version&quot;, version ?? &quot;latest&quot;)
                  .replace(&quot;:path&quot;, path ?? `umd/${name}.production.min.js`),
              },
            };
          }),
        };
      },
    },
  };
};
