const deps = resolvePackageData(&quot;wrong-pkg&quot;, __dirname).data
  .dependencies;

export default defineConfig({
  optimizeDeps: {
    esbuildOptions: {
      plugins: [esbuildCommonjs([...Object.keys(deps)])],
