import { defineConfig, splitVendorChunk } from &quot;vite&quot;;
import react from &quot;@vitejs/plugin-react&quot;;

const getVendorChunk = splitVendorChunk();

export default defineConfig({
  plugins: [react()],
  build: {
    rollupOptions: {
      output: {
        manualChunks: (id, options) =&gt; {
          if (id.indexOf(&quot;react&quot;) !== -1) {
            return &quot;react&quot;;
