const main = (promiseFn, limit) =&gt; {
  const arr = [];
  let index = 0;
  return (...args) =&gt; {
    const handle = (resolvePlus) =&gt; {
      index++;
      promiseFn(...args).then((res) =&gt; {
        index--;
        if (arr.length) {
          arr.shift()();
        }
        resolvePlus(res);
      });
    };

    return new Promise((resolve) =&gt; {
      if (index &lt; limit) {
        handle(resolve);
      } else {
        arr.push(() =&gt; handle(resolve));
      }
    });
  };
}

